// Simple Space Junk Collector game
// Canvas element with id="game" must exist in the page.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.width || 800;
  const H = canvas.height = canvas.height || 600;

  // Game settings
  const shipWidth = 40;
  const shipHeight = 20;
  const hookWidth = 4;
  const hookSpeed = 6;
  const debrisSpeed = 2;
  const spawnInterval = 1000; // ms
  const gameDuration = 60; // seconds

  let left = false, right = false, fire = false;
  let score = 0;
  let timeLeft = gameDuration;
  let lastSpawn = 0;
  let lastTimerTick = performance.now();
  let gameOver = false;

  const ship = {
    x: W / 2 - shipWidth / 2,
    y: H - shipHeight - 5,
    w: shipWidth,
    h: shipHeight,
    speed: 5,
  };

  const hook = {
    active: false,
    extending: false,
    x: 0,
    y: 0,
    length: 0,
    maxLen: H / 2,
  };

  const debris = [];

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') left = true;
    if (e.key === 'ArrowRight') right = true;
    if (e.key === ' ') fire = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft') left = false;
    if (e.key === 'ArrowRight') right = false;
    if (e.key === ' ') fire = false;
  });

  function spawnDebris() {
    const size = Math.random() * 20 + 10;
    const isDanger = Math.random() < 0.2; // asteroid
    debris.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      speed: debrisSpeed + Math.random(),
      danger: isDanger,
      captured: false,
    });
  }

  function update(dt) {
    if (gameOver) return;

    // Move ship
    if (left) ship.x -= ship.speed;
    if (right) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(W - ship.w, ship.x));

    // Hook logic
    if (fire && !hook.active) {
      hook.active = true;
      hook.extending = true;
      hook.x = ship.x + ship.w / 2 - hookWidth / 2;
      hook.y = ship.y;
      hook.length = 0;
    }
    if (hook.active) {
      if (hook.extending) {
        hook.length += hookSpeed;
        if (hook.length >= hook.maxLen) hook.extending = false;
      } else {
        hook.length -= hookSpeed;
        if (hook.length <= 0) hook.active = false;
      }
      // Collision with debris while extending
      if (hook.extending) {
        const tipX = hook.x + hookWidth / 2;
        const tipY = hook.y - hook.length;
        debris.forEach(d => {
          if (!d.captured && tipX > d.x && tipX < d.x + d.w && tipY > d.y && tipY < d.y + d.h) {
            d.captured = true;
            score += d.danger ? 0 : 10; // danger gives no points
          }
        });
      }
    }

    // Update debris
    debris.forEach(d => {
      if (!d.captured) d.y += d.speed;
    });
    // Remove off‑screen or captured debris
    for (let i = debris.length - 1; i >= 0; i--) {
      const d = debris[i];
      if (d.captured) {
        // simple retract effect: nothing to do
        debris.splice(i, 1);
        continue;
      }
      if (d.y > H) {
        // lost debris – end game
        gameOver = true;
      }
      // collision with ship (danger only)
      if (d.danger &&
          d.x < ship.x + ship.w && d.x + d.w > ship.x &&
          d.y < ship.y + ship.h && d.y + d.h > ship.y) {
        gameOver = true;
      }
    }

    // Spawn new debris
    if (performance.now() - lastSpawn > spawnInterval) {
      spawnDebris();
      lastSpawn = performance.now();
    }

    // Timer
    const now = performance.now();
    if (now - lastTimerTick >= 1000) {
      timeLeft--;
      lastTimerTick = now;
      if (timeLeft <= 0) gameOver = true;
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Ship
    ctx.fillStyle = '#0cf';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);

    // Hook
    if (hook.active) {
      ctx.fillStyle = '#fff';
      ctx.fillRect(hook.x, hook.y - hook.length, hookWidth, hook.length);
    }

    // Debris
    debris.forEach(d => {
      ctx.fillStyle = d.danger ? '#f44' : '#aaa';
      ctx.fillRect(d.x, d.y, d.w, d.h);
    });

    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Time: ${timeLeft}`, W - 100, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', W / 2, H / 2 - 20);
      ctx.font = '24px sans-serif';
      ctx.fillText(`Final Score: ${score}`, W / 2, H / 2 + 20);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - (lastFrame || timestamp);
    lastFrame = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  let lastFrame = null;
  requestAnimationFrame(loop);
})();
